import sys

def remaining_water(A, B, C):
    if B + C <= A:
        return 0
    else:
        return (B + C) - A

if __name__ == "__main__":
    input = sys.stdin.read().strip()
    A, B, C = map(int, input.split())
    result = remaining_water(A, B, C)
    print(result)
